import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/02-Programming-thinking-makes-kids-smarter.html","title":"02-编程思维：让你受益终身的解决问题能力","lang":"zh-CN","frontmatter":{"title":"02-编程思维：让你受益终身的解决问题能力","icon":"read","date":"2025-04-10T21:19:17.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1744294015000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":12,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"2b312ff09a729c21916e9f55a427e204e65b3e4d","time":1744350615000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"true"},{"hash":"861388bb0eb9306d3ca70db3b33a217d45b31910","time":1744341330000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"read"},{"hash":"0a66609205105725abbfb952a13a88b509b2eda2","time":1744340384000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"<a href=\\"http://03-How-to-catch-a-robot-spy-with-programming-thinking.md\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">03-How-to-catch-a-robot-spy-with-programming-thinking.md</a>"},{"hash":"ed6b716374e0d1f67e2e9c7a07798bb77547ad9a","time":1744336771000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"在我的这门编程思维课里，我不会直接教你怎么写代码，而是会教给你编程的思维，帮你换个角度思考问题。"},{"hash":"96e8792940f33683cb787b71473f447affa13695","time":1744336028000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"所以在这套课程里，我们不会一开始就手把手教你写代码，而是会通过30个有趣的小故事，带你学会12种常用的思考方法，掌握10种有效的问题解决策略。"},{"hash":"ab56344eaeec432eab8f2b147b834414172c705e","time":1744332707000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"IMG_4161"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cf57e0f4569506ffce341327dab893eb145c88c0","time":1744328117000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新网站"},{"hash":"6354d3c5e148ef8e051b7a39f4c74580fcbc0959","time":1744297683000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"果壳网"},{"hash":"fd8ccbcc09009c16e2529de5e31fa2a549992fad","time":1744294015000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"todo"}]},"readingTime":{"minutes":4.08,"words":1223},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/02-Programming-thinking-makes-kids-smarter.md"}`),a={name:`02-Programming-thinking-makes-kids-smarter.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>当我们提到“编程”，很多人脑海里浮现的第一画面，可能就是程序员对着电脑飞快敲打键盘的样子。确实，写代码是编程的一部分。但如果你以为这就是全部，那就太小看它了。实际上，编程的精髓远不只是写出一行行代码，而更在于培养一种独特的思维方式——也就是“编程思维”。</p><figure><img src="/assets/IMG_4161-Cn1UF03F.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_1-什么是编程思维" tabindex="-1"><a class="header-anchor" href="#_1-什么是编程思维"><span>1. 什么是编程思维？</span></a></h2><p>简单来说，编程思维是一种把复杂问题拆解、转换成更容易解决的小问题，并逐步找到答案的思维方式。这听起来也许有点抽象，那我们换个角度看：</p><p>还记得在数学课上学过的各种面积公式吗？你可以轻松算出长方形或圆形的面积。但如果我现在在纸上画了一只憨态可掬的大熊猫，让你来计算它到底占了多少面积，你会怎么办呢？</p><figure><img src="/assets/raw-D2X1W2Zm.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这时候，编程思维就派上用场了。</p><p>与其苦苦找寻不存在的“熊猫面积公式”，不如换个思路：想象你把这张纸均匀撒上一层小米粒。然后数一数落在熊猫图案上的米粒数量，和总米粒数相比占了多少比例。假如覆盖在熊猫身上的米粒大概占了一半，那它的面积自然也就是纸张面积的一半。</p><p>这正是一种“问题转化”的策略，我们用一个可操作、容易统计的方式（数米粒）来解决一个原本无从下手的问题（图形面积）。而这种方式，在编程世界中有个专业名字：<strong>蒙特卡洛方法</strong>。</p><p>很多看似神奇的人工智能算法，比如击败世界围棋冠军的 AlphaGo，其底层也使用了类似的思路：不断进行随机模拟，从中找出最优答案，使人工智能在围棋领域取得了突破性成就。</p><h2 id="_2-编程思维-不只是为了学编程" tabindex="-1"><a class="header-anchor" href="#_2-编程思维-不只是为了学编程"><span>2. 编程思维，不只是为了学编程</span></a></h2><p>也许你会想，明白这些道理，对我们日常生活有什么用呢？其实编程思维的应用远比你想象的广泛。</p><p>比如，当你学会了如何用“转化”的方式思考问题，你就更容易在生活中找到捷径；当你习惯把一个大问题拆成几步去解决，无论是写作、做项目还是学习新知识，效率都会大大提升。</p><p>这也是为什么越来越多的学校开始重视人工智能和编程课程的原因。在高中阶段，信息技术教材已经开始引入人工智能内容；一些小学、初中也陆续开设了相关课程。</p><p>重点不在于让每个孩子都成为程序员，而是帮助他们建立起面向未来的思维方式。</p><p>对于大人，说的直接一点：有些大人的思维还不如小孩，快快学起来吧！</p><h2 id="_3-用科技工具-更要理解背后的原理" tabindex="-1"><a class="header-anchor" href="#_3-用科技工具-更要理解背后的原理"><span>3. 用科技工具，更要理解背后的原理</span></a></h2><p>你有没有用过“识别植物”的手机 App？拍张照片，它就能告诉你这是什么花。这背后，其实就是人工智能领域中的<strong>机器学习</strong>技术在发挥作用。</p><p>又或者你曾用过美颜滤镜，自动识别你的脸、加上猫耳朵、调大眼睛。别看这些功能看似娱乐，它们涉及的技术原理和识别算法，可是当前 AI 技术的热门方向。</p><p>而当你了解了它们的基本原理，哪怕你不亲自写程序，也能成为一个更聪明、更有判断力的科技使用者。</p><h2 id="_4-从-编程思维-开始-打开看世界的新方式" tabindex="-1"><a class="header-anchor" href="#_4-从-编程思维-开始-打开看世界的新方式"><span>4. 从“编程思维”开始，打开看世界的新方式</span></a></h2><p>所以在本书的这个部分开始，我不会一开始就手把手教你写代码，而是会通过许多个有趣的小故事，带你学会<strong>12种常用的思考方法</strong>，掌握<strong>10种有效的问题解决策略</strong>。</p><p>你会发现，很多科技工具并不神秘，它们的背后，是人类设计出的聪明方法。而这些方法，你也完全能掌握。</p><p>也许你未来会学编程，也许不会。但编程思维一定会在很多场合帮到你，让你更善于分析、更敢于尝试、更有能力独立思考。</p><p>这就是编程思维的魅力——它不止属于程序员，更属于<strong>每一个想要提升自己思维方式的人</strong>。</p>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};